const PLAN_VERSION = 1;

const TYPES = {
    text: {
        sql: "text",
        validate: value => typeof value === "string" && value.length > 0
    },
    integer: {
        sql: "integer",
        validate: Number.isInteger
    },
    float: {
        sql: "double precision",
        validate: Number.isFinite
    },
    timestamptz: {
        sql: "timestamptz",
        validate: value =>
            typeof value === "string" && Number.isFinite(Date.parse(value))
    },
    jsonb: {
        sql: "jsonb",
        validate: value => {
            if (value === undefined) return false;
            try {
                JSON.stringify(value);
                return true;
            } catch {
                return false;
            }
        }
    }
};

const REGISTRY = {
    sensor_readings: {
        columns: {
            device_id: { type: "text", required: true },
            observed_at: { type: "timestamptz", required: true },
            value_mm: { type: "float", required: true }
        },
        conflict: ["device_id", "observed_at"],
        update: ["value_mm"],
        order: 10
    },
    sensor_health: {
        columns: {
            device_id: { type: "text", required: true },
            observed_at: { type: "timestamptz", required: true },
            batt_mv: { type: "integer", required: true },
            rssi_dbm: { type: "float", required: true }
        },
        conflict: ["device_id", "observed_at"],
        update: ["batt_mv", "rssi_dbm"],
        order: 20
    },
    errors: {
        columns: {
            event_id: { type: "text", required: true },
            time: { type: "timestamptz", required: true },
            dev_id: { type: "text", required: true },
            deployment_id: { type: "text", required: true },
            level: { type: "text", required: true },
            message: { type: "text", required: true },
            type: { type: "text", required: true },
            source: { type: "text", required: true },
            data: { type: "jsonb", required: true }
        },
        conflict: ["event_id", "time"],
        update: [],
        order: 100
    }
};

const identifierPattern = /^[A-Za-z_][A-Za-z0-9_]*$/;
const plainObject = value => {
    if (value == null || typeof value !== "object" || Array.isArray(value)) {
        return false;
    }
    const prototype = Object.getPrototypeOf(value);
    return prototype === null || Object.getPrototypeOf(prototype) === null;
};

function validateRegistry() {
    for (const [table, definition] of Object.entries(REGISTRY)) {
        if (!identifierPattern.test(table)) {
            return "invalid table identifier " + table;
        }
        if (!plainObject(definition) || !plainObject(definition.columns)) {
            return table + " must define columns";
        }

        const columns = Object.keys(definition.columns);
        if (!columns.length) return table + " must define at least one column";
        for (const [column, specification] of Object.entries(definition.columns)) {
            if (!identifierPattern.test(column)) {
                return table + " has invalid column identifier " + column;
            }
            if (!plainObject(specification) || !TYPES[specification.type]) {
                return table + "." + column + " has an unknown type";
            }
            if (specification.required !== true) {
                return table + "." + column +
                    " must be required; optional-column semantics are not defined";
            }
        }

        if (!Array.isArray(definition.conflict) || !definition.conflict.length) {
            return table + " must define a conflict key";
        }
        if (!definition.conflict.every(column => columns.includes(column))) {
            return table + " conflict key references an unknown column";
        }
        if (!Array.isArray(definition.update)) {
            return table + " must define an explicit update list";
        }
        if (!definition.update.every(column =>
            columns.includes(column) && !definition.conflict.includes(column)
        )) {
            return table + " update list is unknown or overlaps its conflict key";
        }
        if (!Number.isFinite(definition.order)) {
            return table + " must define a finite order";
        }
    }
    return null;
}

function validatePlan(plan) {
    if (!plainObject(plan)) return "plan must be an object";
    if (plan.version !== PLAN_VERSION) {
        return "unsupported plan version " + plan.version;
    }
    if (typeof plan.eventId !== "string" || !plan.eventId) {
        return "eventId must be a non-empty string";
    }
    if (!plainObject(plan.writes) || !Object.keys(plan.writes).length) {
        return "writes must contain at least one registered table";
    }

    for (const [table, rows] of Object.entries(plan.writes)) {
        const definition = REGISTRY[table];
        if (!definition) return "table " + table + " is not registered";
        if (!Array.isArray(rows) || !rows.length) {
            return table + " must contain at least one row";
        }

        for (const [index, row] of rows.entries()) {
            if (!plainObject(row)) {
                return table + "[" + index + "] must be an object";
            }
            const unknown = Object.keys(row).filter(
                column => !Object.hasOwn(definition.columns, column)
            );
            if (unknown.length) {
                return table + "[" + index + "] has unknown columns: " +
                    unknown.join(", ");
            }
            for (const [column, specification] of Object.entries(definition.columns)) {
                if (!Object.hasOwn(row, column) || row[column] == null) {
                    return table + "[" + index + "]." + column + " is required";
                }
                if (!TYPES[specification.type].validate(row[column])) {
                    return table + "[" + index + "]." + column +
                        " must be " + specification.type;
                }
            }
        }
    }
    return null;
}

const plans = Array.isArray(msg.payload) ? msg.payload : [];
const leases = msg.outbox?.batch;
const registryError = validateRegistry();
if (registryError) {
    msg.outbox = {
        ...msg.outbox,
        retryable: true,
        circuitFailure: true,
        failureClass: "configuration",
        error: "Invalid write-plan registry: " + registryError
    };
    return [null, msg];
}
if (!Array.isArray(leases) || plans.length !== leases.length) {
    msg.outbox = {
        ...msg.outbox,
        retryable: true,
        circuitFailure: true,
        failureClass: "configuration",
        error: "Claim payload and lease metadata are not aligned"
    };
    return [null, msg];
}

const validPlans = [];
const validLeases = [];
const invalidPlans = [];
const invalidLeases = [];
const validationErrors = [];

plans.forEach((plan, index) => {
    const error = validatePlan(plan);
    if (error) {
        invalidPlans.push(plan);
        invalidLeases.push(leases[index]);
        validationErrors.push({
            id: leases[index]?.id,
            eventId: plan?.eventId,
            error
        });
    } else {
        validPlans.push(plan);
        validLeases.push(leases[index]);
    }
});

let invalidMessage = null;
if (invalidPlans.length) {
    invalidMessage = {
        ...msg,
        payload: invalidPlans,
        outbox: {
            ...msg.outbox,
            batch: invalidLeases,
            retryable: false,
            circuitFailure: false,
            failureClass: "data",
            error: JSON.stringify(validationErrors),
            validationErrors
        }
    };
}
if (!validPlans.length) return [null, invalidMessage];

const rowsByTable = Object.fromEntries(
    Object.keys(REGISTRY).map(table => [table, []])
);
for (const plan of validPlans) {
    for (const [table, rows] of Object.entries(plan.writes)) {
        rowsByTable[table].push(...rows);
    }
}
for (const [table, definition] of Object.entries(REGISTRY)) {
    const deduplicated = new Map();
    for (const row of rowsByTable[table]) {
        const key = JSON.stringify(
            definition.conflict.map(column => row[column])
        );
        deduplicated.set(key, row);
    }
    rowsByTable[table] = [...deduplicated.values()];
}

const quoteIdentifier = value => '"' + value.replaceAll('"', '""') + '"';
const quoteLiteral = value => "'" + value.replaceAll("'", "''") + "'";
const definitions = Object.entries(REGISTRY)
    .filter(([table]) => rowsByTable[table].length)
    .sort(([, left], [, right]) => left.order - right.order);
const ctes = ["input(doc) AS (VALUES ($1::jsonb))"];

for (const [index, [table, definition]] of definitions.entries()) {
    const columns = Object.keys(definition.columns);
    const recordDefinition = columns
        .map(column => quoteIdentifier(column) + " " +
            TYPES[definition.columns[column].type].sql)
        .join(", ");
    const selectedColumns = columns
        .map(column => "row_data." + quoteIdentifier(column))
        .join(", ");
    const conflict = definition.conflict.map(quoteIdentifier).join(", ");
    const action = definition.update.length
        ? "UPDATE SET " + definition.update
            .map(column => {
                const quoted = quoteIdentifier(column);
                return quoted + " = EXCLUDED." + quoted;
            })
            .join(", ")
        : "NOTHING";

    ctes.push("upsert_" + index + " AS (\n" +
        "        INSERT INTO " + quoteIdentifier(table) +
        " (" + columns.map(quoteIdentifier).join(", ") + ")\n" +
        "        SELECT " + selectedColumns + "\n" +
        "        FROM input\n" +
        "        CROSS JOIN LATERAL jsonb_to_recordset(\n" +
        "            COALESCE(input.doc -> " + quoteLiteral(table) +
        ", '[]'::jsonb)\n" +
        "        ) AS row_data(" + recordDefinition + ")\n" +
        "        ON CONFLICT (" + conflict + ") DO " + action + "\n" +
        "        RETURNING 1\n" +
        "    )");
}

const counts = definitions
    .map(([table], index) =>
        quoteLiteral(table) + ", (SELECT COUNT(*) FROM upsert_" + index + ")"
    )
    .join(", ");

msg.query = "WITH\n" + ctes.join(",\n") +
    "\nSELECT jsonb_build_object(" + counts + ") AS affected;";
msg.params = [JSON.stringify(rowsByTable)];
msg.payload = validPlans;
msg.outbox = {
    ...msg.outbox,
    batch: validLeases,
    planVersion: PLAN_VERSION,
    planSummary: {
        plans: validPlans.length,
        rows: Object.fromEntries(
            Object.entries(rowsByTable).map(([table, rows]) => [
                table,
                rows.length
            ])
        )
    }
};
return [msg, invalidMessage];

const code = String(msg.error?.code || "");
const dataFailure = /^(22|23)/.test(code);
msg.outbox = {
    ...msg.outbox,
    retryable: !dataFailure,
    circuitFailure: !dataFailure,
    failureClass: dataFailure ? "data" : "infrastructure",
    error: msg.error || "PostgreSQL batch failed"
};
return msg;

const sequence = context.get("sequence") || 0;
context.set("sequence", sequence + 1);

const deviceId = "nosql-sensor-1";
const observedAt = new Date().toISOString();
const eventId = "demo:" + deviceId + ":" + observedAt;

msg.payload = {
    version: 1,
    eventId,
    writes: {
        sensor_readings: [{
            device_id: deviceId,
            observed_at: observedAt,
            value_mm: 100 + (sequence % 50)
        }],
        sensor_health: [{
            device_id: deviceId,
            observed_at: observedAt,
            batt_mv: 4100 - (sequence % 100),
            rssi_dbm: -70 - (sequence % 20)
        }]
    }
};
msg.outbox = {
    dedupeKey: "postgres-plan:v1:" + eventId
};
return msg;

const observedAt = new Date().toISOString();
const eventId = "invalid:" + observedAt;
msg.payload = {
    version: 1,
    eventId,
    writes: {
        sensor_readings: [{
            device_id: "nosql-sensor-invalid",
            observed_at: observedAt
        }]
    }
};
msg.outbox = {
    dedupeKey: "postgres-plan:v1:" + eventId
};
return msg;

const MAX_DEPTH = 6;
const MAX_KEYS = 100;
const MAX_ITEMS = 100;
const MAX_STRING = 8192;

function safeValue(value, seen = new Set(), depth = 0) {
    if (value == null) return value;
    if (typeof value === "string") {
        return value.length <= MAX_STRING
            ? value
            : value.slice(0, MAX_STRING) + "…[truncated]";
    }
    if (typeof value === "boolean") return value;
    if (typeof value === "number") return Number.isFinite(value) ? value : null;
    if (typeof value === "bigint") return value.toString();
    if (typeof value === "undefined") return null;
    if (typeof value === "function" || typeof value === "symbol") {
        return String(value);
    }
    if (depth >= MAX_DEPTH) return "[Maximum depth]";
    if (seen.has(value)) return "[Circular]";

    const tag = Object.prototype.toString.call(value);
    if (tag === "[object Date]") {
        const time = value.getTime();
        return Number.isFinite(time) ? value.toISOString() : "Invalid Date";
    }
    if (Buffer.isBuffer(value)) {
        return {
            type: "Buffer",
            length: value.length,
            base64: value.toString("base64")
        };
    }

    seen.add(value);
    try {
        if (Array.isArray(value)) {
            const result = value.slice(0, MAX_ITEMS)
                .map(child => safeValue(child, seen, depth + 1));
            if (value.length > MAX_ITEMS) {
                result.push("[Additional items truncated]");
            }
            return result;
        }

        const errorObject = tag === "[object Error]";
        const standardKeys = errorObject
            ? ["name", "message", "code", "stack", "cause"]
            : [];
        const keys = [...new Set([...standardKeys, ...Object.keys(value).sort()])]
            .slice(0, MAX_KEYS);
        const result = {};
        for (const key of keys) {
            let child;
            try {
                child = value[key];
            } catch (cause) {
                child = "[Unreadable property: " + cause.message + "]";
            }
            if (child !== undefined) {
                result[key] = safeValue(child, seen, depth + 1);
            }
        }
        return result;
    } finally {
        seen.delete(value);
    }
}

const original = msg;
const caught = msg.error || {};
const source = caught.source || {};
const occurred = new Date(msg.timestamp || Date.now());
const occurredAt = Number.isFinite(occurred.getTime())
    ? occurred.toISOString()
    : new Date().toISOString();
const sourceId = String(source.id || source.name || "nodered");
const sourceName = source.name
    ? String(source.type || "node") + "::" + String(source.name)
    : "nodered";
const occurrence = Number(source.count) || 1;
const identity = msg._msgid
    ? String(msg._msgid)
    : occurredAt + ":" + String(caught.message || "unknown");
const eventId = [
    "nodered-error-v1",
    encodeURIComponent(sourceId),
    encodeURIComponent(identity),
    occurrence
].join(":");

const plan = {
    payload: {
        version: 1,
        eventId,
        writes: {
            errors: [{
                event_id: eventId,
                time: occurredAt,
                dev_id: String(msg.dev_id || "unknown"),
                deployment_id: String(msg.deployment_id || "unknown"),
                level: "error",
                message: String(caught.message || "Unknown Node-RED error"),
                type: "error",
                source: sourceName,
                data: {
                    error: safeValue(caught),
                    originalSensorPayload: safeValue(msg.originalSensorPayload),
                    hypertables: safeValue(msg.hypertables),
                    tables: safeValue(msg.tables)
                }
            }]
        }
    },
    outbox: {
        dedupeKey: "postgres-error:v1:" + eventId
    }
};

return [plan, original];

msg.timestamp = Date.now();
msg.dev_id = "nosql-sensor-1";
msg.deployment_id = "demo-deployment";
msg.error = {
    message: "Example ingestion failure",
    source: {
        id: "demo-transform",
        type: "function",
        name: "Transform reading",
        count: 1
    },
    cause: new Error("Example nested cause")
};
msg.originalSensorPayload = { value: 42 };
return msg;
